-- chair-step: inverse of read_lane_v2_b3_12_workspace_threads — un-enrolls workspace.threads from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'threads' and is_active);
select iam.apply_rls('workspace', 'threads', (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'threads' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workspace' and table_name = 'threads' and is_active));
